), m AS (
  SELECT a.migration_name, a.checksum, a.started_at, coalesce(r.local_eol, '?') AS local_eol,
         CASE WHEN r.name IS NULL THEN 'NOT IN REPO'
              WHEN a.checksum = r.h_lf         THEN 'MATCH: LF text'
              WHEN a.checksum = r.h_crlf       THEN 'MATCH: CRLF text'
              WHEN a.checksum = r.h_lf_nonl    THEN 'MATCH: LF, no final newline'
              WHEN a.checksum = r.h_crlf_nonl  THEN 'MATCH: CRLF, no final newline'
              ELSE 'NO MATCH' END AS result
  FROM _prisma_migrations a LEFT JOIN repo r ON r.name = a.migration_name
  WHERE a.rolled_back_at IS NULL AND a.finished_at IS NOT NULL
)
SELECT migration_name, local_eol, result, started_at::date AS applied_on,
       CASE WHEN result IN ('NO MATCH', 'NOT IN REPO') THEN checksum ELSE left(checksum, 12) END AS azure_checksum
FROM m ORDER BY migration_name;

