    ('20261021090000_add_held_bill','LF','6be79c8935398131140d1e1dac2d39365a5c4d35c5af1b8069c2e217c1a849c5','0cc58b8a8442b18528c5514b5f431da0aabb4b229bd2e05b17ff0cb087abb7b4','24a187dfe0c8e673e50f6d3287747b34f0f443f21e3f6d070bde2030dc3d1e9f','cbe455c34cfa8441d47022b265fde1d9fc64ecdb2fef94292c6b2af070f08cbe'),
    ('20261023130000_add_tcz_billing','LF','60ce284672b1dad10d725cb6bef7738183b0254ed53563e7e8b6da46d933f125','ceee2b1c577386d6531bc6272679ab7436a7d0792f5aba76a2e265524e875854','c459250633394ac9f451bd091880939e4e5538f542f1759c4d8f3d6da621c377','42186534360a1ca7e98b505ba070c76a1390ec488a62d5c7c46d66e7dfe1e0cf')
), m AS (
  SELECT a.migration_name, a.checksum, a.started_at, coalesce(r.local_eol, '?') AS local_eol,
         CASE WHEN r.name IS NULL THEN 'NOT IN REPO'
              WHEN a.checksum = r.h_lf         THEN 'MATCH: LF text'
              WHEN a.checksum = r.h_crlf       THEN 'MATCH: CRLF text'
              WHEN a.checksum = r.h_lf_nonl    THEN 'MATCH: LF, no final newline'
              WHEN a.checksum = r.h_crlf_nonl  THEN 'MATCH: CRLF, no final newline'
              ELSE 'NO MATCH' END AS result
  FROM _prisma_migrations a LEFT JOIN repo r ON r.name = a.migration_name
  WHERE a.rolled_back_at IS NULL AND a.finished_at IS NOT NULL
)
SELECT result, count(*) AS migrations, min(started_at) AS first_started, max(started_at) AS last_started FROM m GROUP BY result ORDER BY 3;

